// Definitive check: does the sheet contain exactly the rows it should,
// and is every column populated as intended?
try {
  var sheetRes = $input.first().json;
  var rows = sheetRes.values || [];
  var header = rows[0] || [];
  var body = rows.slice(1);

  var mcsRes = $('📥 Fetch MCS').first().json;
  var src = (mcsRes && mcsRes.installers) ? mcsRes.installers : [];

  // --- rebuild the expected set using the SAME rules as the pipeline ---
  var TECH = ['solar_pv','ashp','battery','wshp','solar_thermal','eahp'];
  var expected = {};
  var expectedCount = 0;
  for (var i = 0; i < src.length; i++) {
    var r = src[i];
    var techs = r.technologies || [];
    var inScope = false;
    for (var t = 0; t < techs.length; t++) {
      if (TECH.indexOf(techs[t]) !== -1) { inScope = true; break; }
    }
    if (!inScope) { continue; }
    var la = Number(r.latitude), lo = Number(r.longitude);
    if (!(la >= 49.8 && la <= 60.9 && lo >= -8.7 && lo <= 1.9)) { continue; }
    if (!String(r.name || '').trim()) { continue; }
    expected[r.certification_number] = r.name;
    expectedCount++;
  }

  // --- what is actually in the sheet ---
  var iCert = header.indexOf('MCS Cert Number');
  var present = {};
  for (var b = 0; b < body.length; b++) {
    var c = String((body[b] || [])[iCert] || '').trim();
    if (c) { present[c] = true; }
  }

  var missing = [];
  var keys = Object.keys(expected);
  for (var k = 0; k < keys.length; k++) {
    if (!present[keys[k]]) { missing.push({ cert: keys[k], name: expected[keys[k]] }); }
  }
  var unexpected = [];
  var pk = Object.keys(present);
  for (var p = 0; p < pk.length; p++) {
    if (!expected[pk[p]]) { unexpected.push(pk[p]); }
  }

  // --- per-column fill rate: catches misalignment and dead columns ---
  var fill = [];
  for (var col = 0; col < header.length; col++) {
    var n = 0;
    for (var rr = 0; rr < body.length; rr++) {
      var v = (body[rr] || [])[col];
      if (v !== undefined && v !== null && String(v) !== '') { n++; }
    }
    fill.push({ col: col + 1, name: header[col], filled: n,
                pct: Math.round((n / body.length) * 1000) / 10 });
  }

  return [{ json: {
    headerCount: header.length,
    headersInOrder: header,
    dataRows: body.length,
    expectedRows: expectedCount,
    rowDelta: body.length - expectedCount,
    missingCount: missing.length,
    missingRecords: missing.slice(0, 20),
    unexpectedCount: unexpected.length,
    unexpectedCerts: unexpected.slice(0, 20),
    columnFill: fill
  }}];
} catch (e) {
  return [{ json: { _error: 'Integrity check failed: ' + e.message } }];
}
